-- Import into a dedicated website Supabase project, not the LMS database.
-- Source: https://lms.orkendey.kz/catalog, captured 2026-09-24.
create table if not exists public.website_courses (
  lms_id uuid primary key,
  slug text not null unique,
  title text not null,
  description text not null default '',
  language text not null check (language in ('ru','kk')),
  sector text not null check (sector in ('education','healthcare','business','documents')),
  hours integer check (hours > 0),
  duration_review text,
  cover_url text not null,
  lms_url text not null,
  source_snapshot_date date not null,
  updated_at timestamptz not null default now()
);

alter table public.website_courses enable row level security;
revoke all on public.website_courses from anon, authenticated;
grant select on public.website_courses to anon, authenticated;
drop policy if exists "Read website courses" on public.website_courses;
create policy "Read website courses" on public.website_courses
  for select to anon, authenticated using (true);

